(7625075, 1235423, 97225, '<td valign="top">Lol! Rehearsing for a trip to the dentist?</td>', 'Lol! Rehearsing for a trip to the dentist?', '2019-04-19 03:20:45.000000', NULL, 1),
(7625169, 1235318, 24983, '<td valign="top">you know the old saying about giving enough rope to a person ?</td>', 'you know the old saying about giving enough rope to a person ?', '2019-04-20 01:54:20.000000', NULL, 1),
(7625187, 1235696, 100831, '<td valign="top">Best in show IMO. Love the lines and spaces.</td>', 'Best in show IMO. Love the lines and spaces.', '2019-04-20 10:58:21.000000', NULL, 1),
(7625219, 1235725, 2764, '<td valign="top">I read a study recently that says there are distinct facial muscles that only smile with love at a loved one. (In a book called Subliminal by Leonard Mlodinow) Give a child the camera and you get a special picture of his parents.  This is great - see her smile?</td>', 'I read a study recently that says there are distinct facial muscles that only smile with love at a loved one. (In a book called Subliminal by Leonard Mlodinow) Give a child the camera and you get a special picture of his parents.  This is great - see her smile?', '2019-04-20 22:38:55.000000', NULL, 1),
(7625239, 1235691, 30982, '<td valign="top">Yep, this is the way we all see things now.  I do appreciate the one woman in front paying attention to the guide.  I also find it interesting that no one noticed you!</td>', 'Yep, this is the way we all see things now.  I do appreciate the one woman in front paying attention to the guide.  I also find it interesting that no one noticed you!', '2019-04-21 17:04:01.000000', NULL, 1),
(7625240, 1235696, 30982, '<td valign="top">Unfortunate titling of the entry, but an excellent photograph.  Great use of the slow shutter speed.</td>', 'Unfortunate titling of the entry, but an excellent photograph.  Great use of the slow shutter speed.', '2019-04-21 17:04:28.000000', NULL, 1),
(7625241, 1235659, 30982, '<td valign="top">The photograph itself is made far more interesting by the photo on the phone''s screen.  I can''t resolve the angles, though, because it doesn''t look as though the phone is pointing at her.  He must be just viewing the shot after it is taken?</td>', 'The photograph itself is made far more interesting by the photo on the phone''s screen.  I can''t resolve the angles, though, because it doesn''t look as though the phone is pointing at her.  He must be just viewing the shot after it is taken?', '2019-04-21 17:05:38.000000', NULL, 1),
(7625242, 1235728, 30982, '<td valign="top">I love the gold tones to this.  Sweet picture!</td>', 'I love the gold tones to this.  Sweet picture!', '2019-04-21 17:05:58.000000', NULL, 1),
(7625243, 1235423, 30982, '<td valign="top">What great smiles!  Are the two subjects twins?</td>', 'What great smiles!  Are the two subjects twins?', '2019-04-21 17:06:23.000000', NULL, 1),
(7625261, 1235608, 42733, '<td valign="top">+1 for the title. LOL.</td>', '+1 for the title. LOL.', '2019-04-21 20:25:13.000000', NULL, 1),
(7625262, 1235691, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2019-04-21 20:25:57.000000', NULL, 1),
(7625263, 1235728, 42733, '<td valign="top">One of my top picks. Neat capture.</td>', 'One of my top picks. Neat capture.', '2019-04-21 20:26:14.000000', NULL, 1),
(7625479, 1235696, 140305, '<td valign="top">Incredibly good, should easily win the blue!</td>', 'Incredibly good, should easily win the blue!', '2019-04-22 13:04:17.000000', NULL, 1),
(7626300, 1235726, 67258, '<td valign="top">Botallock - Crown Mines, one of my favourite places (and a great place to spot Chough, too).  Super composition - I always struggle with foreground interest.  Shame the light wasn''t working for you a bit better as it can be quite magical at sunset.</td>', 'Botallock - Crown Mines, one of my favourite places (and a great place to spot Chough, too).  Super composition - I always struggle with foreground interest.  Shame the light wasn''t working for you a bit better as it can be quite magical at sunset.', '2019-04-24 07:46:11.000000', NULL, 1),
(7626301, 1235670, 67258, '<td valign="top">A little over-saturated for my taste, but a super composition.</td>', 'A little over-saturated for my taste, but a super composition.', '2019-04-24 07:48:36.000000', NULL, 1),
(7626335, 1235528, 24454, '<td valign="top">I love this!  What spirit it conveys.  I feel like I''m there!</td>', 'I love this!  What spirit it conveys.  I feel like I''m there!', '2019-04-24 13:11:40.000000', NULL, 1),
